import React from "react";
import { palette } from "../theme/palette";
import { archPath, cuspedArchPath } from "./WeddingDaySets";

/*
 * Interior pieces for the wedding day: the jharokha dressing room (Sehra), tied-back drapes,
 * a marble ledge for typography, and a jali balustrade. 1080×1920 scene space.
 */

export const SEHRA_ARCH = { x: 110, w: 860, spring: 820, apex: 250, base: 2200 };

/** Wall with a cusped window opening; the view is drawn underneath by the scene. */
export const JharokhaWall: React.FC<{ wall: string; shade: string }> = ({ wall, shade }) => {
  const a = SEHRA_ARCH;
  const hole = cuspedArchPath(a.x, a.w, a.spring, a.apex, a.base, 9);
  const outer = archPath(a.x - 46, a.w + 92, a.spring, a.apex - 70, a.base);
  const frame = `M-300 -300 H1380 V2300 H-300 Z`;
  return (
    <g>
      <path d={`${frame} ${hole}`} fill={wall} fillRule="evenodd" />
      <path d={`${frame} ${hole}`} fill="url(#jali)" fillRule="evenodd" opacity={0.1} />
      {/* carved frame band around the opening */}
      <path d={`${outer} ${hole}`} fill={shade} fillRule="evenodd" opacity={0.3} />
      <path d={outer} fill="none" stroke={palette.gold} strokeWidth={2} />
      <path
        d={archPath(a.x - 26, a.w + 52, a.spring, a.apex - 40, a.base)}
        fill="none"
        stroke={palette.goldLight}
        strokeWidth={3}
        strokeDasharray="0.1 9"
        strokeLinecap="round"
      />
      <path d={hole} fill="none" stroke={palette.ivoryLight} strokeWidth={12} />
      <path d={hole} fill="none" stroke="url(#foil)" strokeWidth={2.5} />
      {/* spandrel rosettes */}
      {[
        [150, 300],
        [930, 300],
      ].map(([x, y]) => (
        <g key={x} transform={`translate(${x} ${y})`}>
          {new Array(8).fill(0).map((_, i) => (
            <path key={i} d="M0 0 C8 -10 8 -26 0 -34 C-8 -26 -8 -10 0 0 Z" transform={`rotate(${i * 45})`} fill="none" stroke={palette.gold} strokeWidth={1.4} />
          ))}
          <circle r={7} fill="url(#foil)" />
        </g>
      ))}
      {/* keystone ornament */}
      <path d="M540 118 L556 138 L540 158 L524 138 Z" fill="url(#foil)" />
      <rect x={440} y={137} width={76} height={1.4} fill={palette.gold} />
      <rect x={564} y={137} width={76} height={1.4} fill={palette.gold} />
      {/* pilasters at the frame edges */}
      {[34, 1046].map((x) => (
        <g key={x}>
          <rect x={x - 24} y={560} width={48} height={1500} fill={shade} opacity={0.3} />
          <rect x={x - 28} y={546} width={56} height={14} fill="url(#foil-v)" />
          <rect x={x - 0.6} y={600} width={1.2} height={1400} fill={palette.gold} opacity={0.7} />
        </g>
      ))}
    </g>
  );
};

/** Low jali balustrade of a balcony. */
export const JaliRailing: React.FC<{ y: number; x0: number; x1: number; fill: string; shade: string; h?: number }> = ({ y, x0, x1, fill, shade, h = 130 }) => (
  <g>
    <rect x={x0} y={y} width={x1 - x0} height={h} fill={fill} />
    <rect x={x0} y={y} width={x1 - x0} height={h} fill="url(#jali)" opacity={0.55} />
    <rect x={x0} y={y - 16} width={x1 - x0} height={18} fill={shade} />
    <rect x={x0} y={y - 16} width={x1 - x0} height={3} fill={palette.goldLight} />
    {new Array(Math.floor((x1 - x0) / 120) + 1).fill(0).map((_, i) => (
      <rect key={i} x={x0 + i * 120 - 7} y={y} width={14} height={h} fill={shade} />
    ))}
  </g>
);

/** Tied-back sheer drape hanging down one side of an arch (mirror with `flip`). */
export const Drape: React.FC<{ x: number; y: number; h: number; w: number; color: string; edge: string; flip?: boolean; sway?: number; tie?: string }> = ({
  x,
  y,
  h,
  w,
  color,
  edge,
  flip,
  sway = 0,
  tie = palette.maroon,
}) => {
  const inner = `M${w} 0 C${w * 0.8 + sway} ${h * 0.2} ${w * 0.4 + sway} ${h * 0.42} ${w * 0.22} ${h * 0.55} C${w * 0.3} ${h * 0.7} ${w * 0.5} ${h * 0.86} ${w * 0.62} ${h}`;
  return (
    <g transform={`translate(${x} ${y}) ${flip ? "scale(-1 1)" : ""}`}>
      <path d={`M0 0 L${w} 0 ${inner.replace(/^M[^C]+/, "")} L0 ${h} Z`} fill={color} opacity={0.9} />
      <path d={inner} fill="none" stroke={edge} strokeWidth={5} />
      {[0.3, 0.55, 0.78].map((k) => (
        <path
          key={k}
          d={`M${w * k} 0 C${w * k * 0.7 + sway * k} ${h * 0.25} ${w * 0.16} ${h * 0.45} ${w * 0.12} ${h * 0.55} C${w * 0.16} ${h * 0.7} ${w * k * 0.5} ${h * 0.85} ${w * k * 0.6} ${h}`}
          fill="none"
          stroke="#000"
          strokeWidth={1.6}
          opacity={0.07}
        />
      ))}
      <path
        d={`M-4 ${h * 0.535} C${w * 0.1} ${h * 0.515} ${w * 0.25} ${h * 0.535} ${w * 0.31} ${h * 0.57} L${w * 0.3} ${h * 0.595} C${w * 0.2} ${h * 0.57} ${w * 0.08} ${h * 0.57} -4 ${h * 0.58} Z`}
        fill="url(#foil)"
      />
      <circle cx={w * 0.15} cy={h * 0.56} r={9} fill={tie} stroke={palette.gold} strokeWidth={1.5} />
      <rect x={w * 0.15 - 0.7} y={h * 0.56 + 9} width={1.4} height={56} fill={palette.gold} />
      <path d={`M${w * 0.15 - 6} ${h * 0.56 + 64} L${w * 0.15 + 6} ${h * 0.56 + 64} L${w * 0.15 + 3} ${h * 0.56 + 90} L${w * 0.15 - 3} ${h * 0.56 + 90} Z`} fill={tie} />
    </g>
  );
};

/** Ivory marble ledge across the bottom of a frame with gold inlay (a surface for the title). */
export const MarbleLedge: React.FC<{ y: number; color?: string; edge?: string }> = ({ y, color = palette.ivoryLight, edge = palette.ivoryShade }) => (
  <g>
    <rect x={-300} y={y} width={1680} height={2300 - y} fill={color} />
    <rect x={-300} y={y} width={1680} height={12} fill={edge} />
    <rect x={-300} y={y + 12} width={1680} height={2} fill={palette.gold} />
    <rect x={-300} y={y + 24} width={1680} height={1} fill={palette.gold} opacity={0.6} />
    {new Array(16).fill(0).map((_, i) => (
      <path key={i} d={`M${i * 90 - 180} ${y + 40} l9 9 l-9 9 l-9 -9 Z`} fill="none" stroke={palette.goldLight} strokeWidth={1} opacity={0.6} />
    ))}
  </g>
);
